-- Caleris Masters member dashboard and account profile foundation.
-- Account identity is separate from the game member/character record.
-- Members cannot self-assign member_id, role, team, contract, or balance.
create table if not exists public.site_admins (user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table if not exists public.site_content (id uuid primary key default gen_random_uuid(), slug text not null unique, content jsonb not null default '{}'::jsonb, published boolean not null default false, updated_by uuid references auth.users(id) on delete set null, updated_at timestamptz not null default now());
create table if not exists public.site_settings (key text primary key, value jsonb not null, updated_by uuid references auth.users(id) on delete set null, updated_at timestamptz not null default now());
create table if not exists public.teams (id uuid primary key default gen_random_uuid(), name text not null, created_at timestamptz not null default now());
create table if not exists public.members (id uuid primary key default gen_random_uuid(), member_code text unique, character_name text, role text check (role in ('Driver','Principal','Owner','Agent','Journalist','FIA')), license text, team_id uuid references public.teams(id) on delete set null, balance numeric(18,2), created_at timestamptz not null default now());
create table if not exists public.profiles (user_id uuid primary key references auth.users(id) on delete cascade, member_id uuid unique references public.members(id) on delete set null, avatar_url text, web_nickname text, driver_nickname text, updated_at timestamptz not null default now());
create table if not exists public.contracts (id uuid primary key default gen_random_uuid(), member_id uuid not null references public.members(id) on delete cascade, team_id uuid references public.teams(id) on delete set null, duration_label text, starts_on date, ends_on date, salary numeric(18,2), target jsonb, release_clause numeric(18,2), status text not null default 'active', created_at timestamptz not null default now());
alter table public.site_admins enable row level security;
alter table public.site_content enable row level security;
alter table public.site_settings enable row level security;
alter table public.teams enable row level security;
alter table public.members enable row level security;
alter table public.profiles enable row level security;
alter table public.contracts enable row level security;
drop policy if exists "Admins can verify own admin record" on public.site_admins;
create policy "Admins can verify own admin record" on public.site_admins for select to authenticated using (user_id = (select auth.uid()));
drop policy if exists "Public can read published site content" on public.site_content;
create policy "Public can read published site content" on public.site_content for select to anon, authenticated using (published = true);
drop policy if exists "Admins manage site content" on public.site_content;
create policy "Admins manage site content" on public.site_content for all to authenticated using (exists (select 1 from public.site_admins a where a.user_id = (select auth.uid()))) with check (exists (select 1 from public.site_admins a where a.user_id = (select auth.uid())));
drop policy if exists "Public can read community invite setting" on public.site_settings;
create policy "Public can read community invite setting" on public.site_settings for select to anon, authenticated using (key = 'community_invite_url');
drop policy if exists "Admins manage site settings" on public.site_settings;
create policy "Admins manage site settings" on public.site_settings for all to authenticated using (exists (select 1 from public.site_admins a where a.user_id = (select auth.uid()))) with check (exists (select 1 from public.site_admins a where a.user_id = (select auth.uid())));
drop policy if exists "Users read own profile" on public.profiles;
create policy "Users read own profile" on public.profiles for select to authenticated using (user_id = (select auth.uid()));
drop policy if exists "Admins read all profiles" on public.profiles;
create policy "Admins read all profiles" on public.profiles for select to authenticated using (exists (select 1 from public.site_admins a where a.user_id = (select auth.uid())));
drop policy if exists "Users create own profile" on public.profiles;
create policy "Users create own profile" on public.profiles for insert to authenticated with check (user_id = (select auth.uid()));
drop policy if exists "Users update own account fields" on public.profiles;
create policy "Users update own account fields" on public.profiles for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
drop policy if exists "Members read linked member record" on public.members;
create policy "Members read linked member record" on public.members for select to authenticated using (exists (select 1 from public.profiles p where p.user_id = (select auth.uid()) and p.member_id = members.id) or exists (select 1 from public.site_admins a where a.user_id = (select auth.uid())));
drop policy if exists "Members read linked team" on public.teams;
create policy "Members read linked team" on public.teams for select to authenticated using (exists (select 1 from public.members m join public.profiles p on p.member_id = m.id where p.user_id = (select auth.uid()) and m.team_id = teams.id) or exists (select 1 from public.site_admins a where a.user_id = (select auth.uid())));
drop policy if exists "Members read own contracts" on public.contracts;
create policy "Members read own contracts" on public.contracts for select to authenticated using (exists (select 1 from public.profiles p where p.user_id = (select auth.uid()) and p.member_id = contracts.member_id) or exists (select 1 from public.site_admins a where a.user_id = (select auth.uid())));
grant select on public.site_admins to authenticated;
grant select on public.site_content, public.site_settings to anon, authenticated;
grant insert, update, delete on public.site_content, public.site_settings to authenticated;
grant select on public.profiles, public.members, public.teams, public.contracts to authenticated;
grant insert (user_id, avatar_url, web_nickname, driver_nickname, updated_at) on public.profiles to authenticated;
grant update (user_id, avatar_url, web_nickname, driver_nickname, updated_at) on public.profiles to authenticated;
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('profile-avatars','profile-avatars',true,3145728,array['image/png','image/jpeg','image/webp','image/gif']) on conflict (id) do update set public=excluded.public,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists "Public can view profile avatars" on storage.objects;
create policy "Public can view profile avatars" on storage.objects for select to public using (bucket_id='profile-avatars');
drop policy if exists "Users upload own profile avatar" on storage.objects;
create policy "Users upload own profile avatar" on storage.objects for insert to authenticated with check (bucket_id='profile-avatars' and (storage.foldername(name))[1]=(select auth.uid())::text);
drop policy if exists "Users update own profile avatar" on storage.objects;
create policy "Users update own profile avatar" on storage.objects for update to authenticated using (bucket_id='profile-avatars' and (storage.foldername(name))[1]=(select auth.uid())::text) with check (bucket_id='profile-avatars' and (storage.foldername(name))[1]=(select auth.uid())::text);
drop policy if exists "Users delete own profile avatar" on storage.objects;
create policy "Users delete own profile avatar" on storage.objects for delete to authenticated using (bucket_id='profile-avatars' and (storage.foldername(name))[1]=(select auth.uid())::text);
